/**
 * Auto-bundled production image assets for Cloudflare Pages & GitHub deployment
 */

export const HERO_SHOWROOM_IMG = "data:image/jpeg;base64,";
export const WORKSHOP_IMG = "data:image/jpeg;base64,";
export const STRADA_PICKUP_IMG = "data:image/jpeg;base64,";
export const FASTBACK_SUV_IMG = "data:image/jpeg;base64,";
export const PULSE_CROSSOVER_IMG = "data:image/jpeg;base64,";
export const SIGNAGE_PHOTO_IMG = "data:image/jpeg;base64,";
export const FLYER_PHOTO_IMG = "data:image/jpeg;base64,";

export function resolveAssetUrl(url: string): string {
  if (!url) return HERO_SHOWROOM_IMG;
  if (url.includes("hero_fiat_showroom")) return HERO_SHOWROOM_IMG;
  if (url.includes("official_service_workshop")) return WORKSHOP_IMG;
  if (url.includes("fiat_strada_pickup")) return STRADA_PICKUP_IMG;
  if (url.includes("fiat_fastback_suv")) return FASTBACK_SUV_IMG;
  if (url.includes("fiat_pulse_crossover")) return PULSE_CROSSOVER_IMG;
  if (url.includes("_4BFD534B") || url.includes("ronel_signage")) return SIGNAGE_PHOTO_IMG;
  if (url.includes("image_870ea488") || url.includes("ronel_flyer")) return FLYER_PHOTO_IMG;
  return url;
}
